#!/bin/bash
# run_six_scenarios.sh — run the 6 AI53_017 channel scenarios (path A & B,
# gt/2nn/nerf), then overlay with multiplot.
#
#   ./run_six_scenarios.sh [SNR] [OUT_DIR] [DURATION]
#
# PREREQ: CPU isolation must be set this boot, or UL MCS stays pinned at 6:
#   sudo ../setup_cpu_isolation.sh
#   (and re-apply FIFO:80 to nr-softmodem once the gNB is up — see cmd book)
#
# Channels come from channel/raj_chan/20261009/ (generated by
# generate_20261009.py from Downloads/raj_cir/AI53_017.zip).
# Each run is ~3-4 min wall-clock, so the six take ~20 min; multiplot at the end.

set -u

source /home/ways_lab/repos/venv/sub6isac_env/bin/activate

EXP="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"   # .../202610raj
RPI="$(dirname "$EXP")"                                # .../tti_experiments_rpi

# soft reminder if the isolated cores still have host tasks on them
eff=$(cat /sys/fs/cgroup/system.slice/cpuset.cpus.effective 2>/dev/null || echo "")
if [[ "$eff" != "0-4,10-14" ]]; then
  echo "WARNING: CPU isolation may not be active (system.slice cpus = '${eff:-?}')."
  echo "         Run 'sudo ../setup_cpu_isolation.sh' first or MCS may stay at 6."
fi

cd "$EXP"

SNR="${1:-30}"
OUT_DIR="${2:-./plot}"
DURATION="${3:-80}"

# UL/DL traffic. Overridable by env so the same script can do TCP-sat or UDP:
#   default: UL = saturating TCP (max throughput, but collapses on weak links)
#   UDP:     UL_PROTO=udp UL_RATE=50M  (connectionless, survives weak links)
# DL is always UDP; keep it low (1M) so it doesn't starve the UL path.
UL_RATE="${UL_RATE:-sat}"
UL_PROTO="${UL_PROTO:-tcp}"
DL_RATE="${DL_RATE:-1M}"

echo "=== six scenarios: snr=$SNR out=$OUT_DIR dur=${DURATION}s (ul=$UL_RATE/$UL_PROTO dl=$DL_RATE) ==="

run() {  # <channel> <out-subdir>
  echo "=== [$(date +%H:%M:%S)] $2 : $1  (snr=$SNR dur=${DURATION}s ul=$UL_RATE/$UL_PROTO dl=$DL_RATE) ==="
  python3 raj_tti_experiment.py 1 1 --channel "$1" --snr "$SNR" --duration "$DURATION" \
          --ul-rate "$UL_RATE" --ul-proto "$UL_PROTO" --dl-rate "$DL_RATE" --out "$OUT_DIR/$2/"
}

# path A
run 20261009/channel_gt_A.txt    pathA_gt
run 20261009/channel_2nn_A.txt   pathA_2nn
run 20261009/channel_nerf_A.txt  pathA_nerf
# path B
run 20261009/channel_gt_B.txt    pathB_gt
run 20261009/channel_2nn_B.txt   pathB_2nn
run 20261009/channel_nerf_B.txt  pathB_nerf

# multiplot reads paths relative to its JSON's own folder, so drop a copy of the
# config into OUT_DIR and point multiplot at it (works for any OUT_DIR).
echo "=== [$(date +%H:%M:%S)] overlay: multiplot ==="
mkdir -p "$OUT_DIR"
MP_JSON="$OUT_DIR/multiplot.json"
[ "$(readlink -f "$MP_JSON")" = "$(readlink -f "$EXP/plot/multiplot.json")" ] || cp "$EXP/plot/multiplot.json" "$MP_JSON"
# stamp the actual SNR anchor into this copy's title so each run disambiguates
python3 - "$MP_JSON" "$SNR" <<'PY'
import json, sys
p, snr = sys.argv[1], sys.argv[2]
with open(p) as f: cfg = json.load(f)
cfg["title"] = f"202610raj UL metrics — AI53_017 path A/B gt/2nn/nerf (--snr {snr})"
with open(p, "w") as f: json.dump(cfg, f, indent=2)
PY
cd "$RPI"
python3 multiplot.py "202610raj/${OUT_DIR#./}/multiplot.json"

echo "=== done. outputs in $OUT_DIR/ (multiplot*.png, multiplot_results.txt) ==="
